﻿using System;
using System.Linq;
using System.Threading.Tasks;
using System.Web;
using System.Web.Mvc;
using Microsoft.AspNet.Identity;
using Microsoft.AspNet.Identity.Owin;
using Microsoft.Owin.Security;
using $safeprojectname$.Models;

namespace $safeprojectname$.Controllers
{
[Authorize]
public class ManageController : Controller
{
private ApplicationSignInManager _signInManager;
private ApplicationUserManager _userManager;

public ManageController()
{
}

public ManageController(ApplicationUserManager userManager, ApplicationSignInManager signInManager)
{
UserManager = userManager;
SignInManager = signInManager;
}

public ApplicationSignInManager SignInManager
{
get
{
return _signInManager ?? HttpContext.GetOwinContext().GetApplicationSignInManager();
}
private set 
{ 
_signInManager = value; 
}
}

public ApplicationUserManager UserManager
{
get
{
return _userManager ?? HttpContext.GetOwinContext().GetUserManagerApplicationUserManager();
}
private set
{
_userManager = value;
}
}

//
// GET: /Manage/Index
public async TaskActionResult Index(ManageMessageId? message)
{
ViewBag.StatusMessage =
message == ManageMessageId.ChangeVAE_EDITED_TEXTSuccess ? Your VAE_EDITED_TEXT has been changed.
: message == ManageMessageId.SetVAE_EDITED_TEXTSuccess ? Your VAE_EDITED_TEXT has been set.
: message == ManageMessageId.SetTwoFactorSuccess ? Your two-factor authentication provider has been set.
: message == ManageMessageId.Error ? An error has occurred.
: message == ManageMessageId.AddPhoneSuccess ? Your phone number was added.
: message == ManageMessageId.RemovePhoneSuccess ? Your phone number was removed.
: ;

var userId = User.Identity.GetUserId();
var model = new IndexViewModel
{
HasVAE_EDITED_TEXT = HasVAE_EDITED_TEXT(),
PhoneNumber = await UserManager.GetPhoneNumberAsync(userId),
TwoFactor = await UserManager.GetTwoFactorEnabledAsync(userId),
Logins = await UserManager.GetLoginsAsync(userId),
BrowserRemembered = await AuthenticationManager.TwoFactorBrowserRememberedAsync(userId)
};
return View(model);
}

//
// POST: /Manage/RemoveLogin
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult RemoveLogin(string loginProvider, string providerKey)
{
ManageMessageId? message;
var result = await UserManager.RemoveLoginAsync(User.Identity.GetUserId(), new UserLoginInfo(loginProvider, providerKey));
if (result.Succeeded)
{
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
message = ManageMessageId.RemoveLoginSuccess;
}
else
{
message = ManageMessageId.Error;
}
return RedirectToAction(ManageLogins, new { Message = message });
}

//
// GET: /Manage/AddPhoneNumber
public ActionResult AddPhoneNumber()
{
return View();
}

//
// POST: /Manage/AddPhoneNumber
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult AddPhoneNumber(AddPhoneNumberViewModel model)
{
if (!ModelState.IsValid)
{
return View(model);
}
// Generate the token and send it
var code = await UserManager.GenerateChangePhoneNumberTokenAsync(User.Identity.GetUserId(), model.Number);
if (UserManager.SmsService != null)
{
var message = new IdentityMessage
{
Destination = model.Number,
Body = Your security code is:  + code
};
await UserManager.SmsService.SendAsync(message);
}
return RedirectToAction(VerifyPhoneNumber, new { PhoneNumber = model.Number });
}

//
// POST: /Manage/EnableTwoFactorAuthentication
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult EnableTwoFactorAuthentication()
{
await UserManager.SetTwoFactorEnabledAsync(User.Identity.GetUserId(), true);
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
return RedirectToAction(Index, Manage);
}

//
// POST: /Manage/DisableTwoFactorAuthentication
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult DisableTwoFactorAuthentication()
{
await UserManager.SetTwoFactorEnabledAsync(User.Identity.GetUserId(), false);
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
return RedirectToAction(Index, Manage);
}

//
// GET: /Manage/VerifyPhoneNumber
public async TaskActionResult VerifyPhoneNumber(string phoneNumber)
{
var code = await UserManager.GenerateChangePhoneNumberTokenAsync(User.Identity.GetUserId(), phoneNumber);
// Send an SMS through the SMS provider to verify the phone number
return phoneNumber == null ? View(Error) : View(new VerifyPhoneNumberViewModel { PhoneNumber = phoneNumber });
}

//
// POST: /Manage/VerifyPhoneNumber
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult VerifyPhoneNumber(VerifyPhoneNumberViewModel model)
{
if (!ModelState.IsValid)
{
return View(model);
}
var result = await UserManager.ChangePhoneNumberAsync(User.Identity.GetUserId(), model.PhoneNumber, model.Code);
if (result.Succeeded)
{
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
return RedirectToAction(Index, new { Message = ManageMessageId.AddPhoneSuccess });
}
// If we got this far, something failed, redisplay form
ModelState.AddModelError(, Failed to verify phone);
return View(model);
}

//
// GET: /Manage/RemovePhoneNumber
public async TaskActionResult RemovePhoneNumber()
{
var result = await UserManager.SetPhoneNumberAsync(User.Identity.GetUserId(), null);
if (!result.Succeeded)
{
return RedirectToAction(Index, new { Message = ManageMessageId.Error });
}
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
return RedirectToAction(Index, new { Message = ManageMessageId.RemovePhoneSuccess });
}

//
// GET: /Manage/ChangeVAE_EDITED_TEXT
public ActionResult ChangeVAE_EDITED_TEXT()
{
return View();
}

//
// POST: /Manage/ChangeVAE_EDITED_TEXT
[HttpPost]
[ValidateAntiForgeryToken]
public async TaskActionResult ChangeVAE_EDITED_TEXT(ChangeVAE_EDITED_TEXTViewModel model)
{
if (!ModelState.IsValid)
{
return View(model);
}
var result = await UserManager.ChangeVAE_EDITED_TEXTAsync(User.Identity.GetUserId(), model.OldVAE_EDITED_TEXT, model.NewVAE_EDITED_TEXT);
if (result.Succeeded)
{
var user = await UserManager.FindByIdAsync(User.Identity.GetUserId());
if (user != null)
{
await SignInManager.SignInAsync(user, isPersistent: false, rememberBrowser: false);
}
return RedirectToAction(Index, new { Message = ManageMessageId.ChangeVAE_EDITED_TEXTSuccess });
}
AddErrors(result);
return View(model);
}

