script language=javascript
(function () {
var searchInput = document.getElementById(searchTerm),
searchSubmit = document.getElementById(searchSubmit);
var executeSearchQuery = function () {
var searchTerm = searchInput.value;
if (searchTerm === undefined || searchTerm === &apos;&apos;) {
return false;
}
parent.window.location.href = &apos;https://aetnet.aetna.com/essentialssearch/search-results-prod.html?query=&apos; +  searchTerm;
};

var captureSubmit = function (key) {
key = (key.keyCode || key.which);
if (key === 13) {
executeSearchQuery();
}
};

if (document.addEventListener) {
searchInput.addEventListener(&apos;keyup&apos;, captureSubmit);
searchSubmit.addEventListener(&apos;click&apos;, executeSearchQuery);
}
else {
searchInput.attachEvent(&apos;onkeyup&apos;, captureSubmit);
searchSubmit.attachEvent(&apos;onclick&apos;, executeSearchQuery);
}
})();
/script

