getSelectedQueryDetails(UserQueryID);
}
enable_cb();

function enable_cb() {
if (this.checked) {
$(.boldCheckBox).removeAttr(disabled);
} else {
$(.boldCheckBox).attr(disabled, true);
}
}



$(&apos;.checkboxstyle&apos;).click(function () {
var className = $(this).attr(class);
var checkedState = $(this).prop(checked);
className = className.replace(&apos;checkboxstyle &apos;, &apos;&apos;);
if ($(# + className) != null) {
var isAllSameState = true;
$(. + className).each(function () {
if ($(this).prop(checked) != checkedState) {
isAllSameState = false;
}
});
if (isAllSameState) {
$(# + className).prop(&apos;checked&apos;, checkedState);
}
else {
$(# + className).prop(&apos;checked&apos;, false);
}
}
var divId = $(this).closest(div[id^=&apos;tab&apos;]).attr(&apos;id&apos;);
updateCheckedCountTabNames(divId);
});

$(.DivEzQueryRows).click(function () {
var target = $(event.target);
if (target.is(&apos;input:checkbox&apos;)) return;
var checkbox = $(this).find(input[type=&apos;checkbox&apos;]);
var className = checkbox.attr(class);

if (!checkbox.prop(checked)) {
checkbox.prop(checked, true);
} else {
checkbox.prop(checked, false);
}

var checkedState = checkbox.prop(checked);
if (className != undefined &amp;&amp; className.indexOf(checkboxstyle) = 0) {
className = className.replace(&apos;checkboxstyle &apos;, &apos;&apos;);
if ($(# + className) != null) {
var isAllSameState = true;
$(. + className).each(function () {
if ($(this).prop(checked) != checkedState) {
isAllSameState = false;
}
});
if (isAllSameState) {
$(# + className).prop(&apos;checked&apos;, checkedState);
}
else {
$(# + className).prop(&apos;checked&apos;, false);
}
}
var divId = checkbox.closest(div[id^=&apos;tab&apos;]).attr(&apos;id&apos;);
updateCheckedCountTabNames(divId);
}
});



$(.checkALLCheckBox).click(function () {
var tabId = $(this).closest(div[id^=&apos;tab&apos;]).attr(&apos;id&apos;);
$(&apos;#&apos; + tabId + &apos; :checkbox&apos;).prop(&apos;checked&apos;, true)
updateCheckedCountTabNames(tabId);
});



$(.uncheckALLCheckBox).click(function () {
var tabId = $(this).closest(div[id^=&apos;tab&apos;]).attr(&apos;id&apos;);
$(&apos;#&apos; + tabId + &apos; :checkbox&apos;).prop(&apos;checked&apos;, false)
updateCheckedCountTabNames(tabId);
});

$(.tabClass).hide();
$(.Plans).show();

$(.leftmenuClass).click(function () {
$(.tabClass).hide();
$(. + $(this).attr(id)).show();
var tabName = $($(. + $(this).attr(id))[0]).attr(href);
var index = $(tabName).index();
$(#tabs).tabs({ active: index - 1 });
$(.leftmenuClasslist).attr(class, leftmenuClasslist);
$(this).parent().attr(class, leftmenuClasslist active);
});
});
}
