function getUrlVars() {
var vars = [], hash;
var hashes = window.location.href.slice(window.location.href.indexOf(&apos;?&apos;) + 1).split(&apos;&amp;&apos;);
for (var i = 0; i  hashes.length; i++) {
hash = hashes[i].split(&apos;=&apos;);
vars.push(hash[0]);
vars[hash[0]] = hash[1];
}
return vars;
}

function getLoginData() {
var rememberMe = False;
if ($(#chkRememberMe).is(&apos;:checked&apos;)) rememberMe = True;
var loginDetails = &apos;{LoginID:&apos; + $(#txtZID).val() + &apos;,VAE_EDITED_TEXT:&apos; + $(#txtVAE_EDITED_TEXT).val() + &apos;,RememberMe:&apos; + rememberMe + &apos;}&apos;;
return loginDetails;
}

function IsCompareOptionEnabledForUser() {
